/* Việt Sử V5.8 — bài học SGK Lịch sử lớp 6, 7 (sinh bởi tools/build_v58.py, đừng sửa tay) */
window.VS58_SGK={"phien_ban":"5.8","lop":{"6":{"sach":"Lịch sử và Địa lí 6 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 7–94","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Lịch sử và cuộc sống","trang":[9,10],"nam":null,"tom":"Mọi sự vật, con người và xã hội đều thay đổi theo thời gian; sự thay đổi ấy chính là lịch sử. Học lịch sử giúp ta hiểu cội nguồn, rút kinh nghiệm từ quá khứ để sống tốt hơn hôm nay.","muc":[["1. Lịch sử là gì?",["Lịch sử là tất cả những gì đã diễn ra trong quá khứ, từ một chiếc máy tính, một ngôi làng đến cả xã hội loài người.","Lịch sử còn là một ngành khoa học: nghiên cứu, tìm hiểu và phục dựng lại quá khứ dựa trên các dấu vết còn lại.","Môn Lịch sử ở trường tìm hiểu quá trình hình thành và phát triển của xã hội loài người, từ khi con người xuất hiện đến ngày nay."]],["2. Vì sao phải học lịch sử?",["Để biết cội nguồn của bản thân, gia đình, quê hương, dân tộc và nhân loại.","Để hiểu vì sao hiện tại lại như ngày nay, từ đó đúc rút bài học kinh nghiệm cho cuộc sống.","Người xưa đã ghi chép, biên soạn sử sách để lưu giữ kí ức và truyền lại cho đời sau; học sử là tiếp nối truyền thống ấy."]]],"nho":["Lịch sử là những gì đã xảy ra trong quá khứ và là khoa học phục dựng quá khứ.","Môn Lịch sử nghiên cứu quá trình phát triển của xã hội loài người.","Học lịch sử để hiểu cội nguồn và rút bài học cho hiện tại."],"hoi":["Em hiểu lịch sử là gì? Cho một ví dụ về sự thay đổi theo thời gian ở nơi em sống.","Vì sao chúng ta cần học lịch sử?","Theo em, việc ghi chép lại lịch sử gia đình có ý nghĩa gì?"]},{"so":2,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Dựa vào đâu để biết và phục dựng lại lịch sử?","trang":[11,13],"nam":null,"tom":"Các nhà sử học dựng lại quá khứ nhờ những dấu vết người xưa để lại, gọi là tư liệu lịch sử. Có bốn loại cơ bản: tư liệu hiện vật, chữ viết, truyền miệng và tư liệu gốc.","muc":[["1. Tư liệu hiện vật",["Là những di tích, đồ vật của người xưa còn giữ lại trong lòng đất hay trên mặt đất: công cụ, đồ gốm, trống đồng, đền tháp, thành luỹ…","Hiện vật cho biết khá cụ thể và trung thực về đời sống vật chất, một phần đời sống tinh thần của người xưa."]],["2. Tư liệu chữ viết",["Là những bản ghi, sách vở, văn bia, sắc phong… được viết tay hoặc in, khắc bằng chữ.","Ví dụ: các bia Tiến sĩ ở Văn Miếu – Quốc Tử Giám ghi tên người đỗ đạt qua nhiều khoa thi.","Chữ viết giúp ta biết tương đối đầy đủ về đời sống con người, nhưng có thể mang dấu ấn chủ quan của người viết."]],["3. Tư liệu truyền miệng",["Là truyền thuyết, thần thoại, ca dao, câu chuyện được kể lại từ đời này sang đời khác (ví dụ: Sơn Tinh – Thuỷ Tinh, Thánh Gióng).","Cho biết nhiều điều về quá khứ và tâm tư của người xưa, nhưng cần đối chiếu với tư liệu khác để tìm ra sự thật."]],["4. Tư liệu gốc",["Là tư liệu liên quan trực tiếp đến sự kiện, ra đời ngay lúc sự kiện xảy ra hoặc do người trong cuộc để lại.","Đây là nguồn đáng tin cậy nhất khi tìm hiểu lịch sử."]]],"nho":["Tư liệu hiện vật: đồ vật, di tích của người xưa.","Tư liệu chữ viết: sách, văn bản, văn bia ghi lại sự kiện.","Tư liệu truyền miệng: truyện kể, truyền thuyết lưu truyền qua nhiều đời.","Tư liệu gốc ra đời cùng lúc với sự kiện, có giá trị tin cậy cao nhất."],"hoi":["Kể tên bốn loại tư liệu lịch sử và cho mỗi loại một ví dụ.","Vì sao bia Tiến sĩ ở Văn Miếu được coi là tư liệu chữ viết?","Ở nơi em sống có hiện vật nào giúp tìm hiểu quá khứ của quê hương?"]},{"so":3,"chuong":"Chương 1. Vì sao phải học lịch sử?","ten":"Thời gian trong lịch sử","trang":[14,15],"nam":null,"tom":"Muốn hiểu lịch sử phải biết sự kiện xảy ra khi nào. Bài học giới thiệu âm lịch, dương lịch, Công nguyên và cách tính, ghi các mốc thời gian.","muc":[["1. Vì sao phải xác định thời gian trong lịch sử?",["Các sự kiện nối tiếp nhau theo trình tự trước – sau; biết thời gian xảy ra mới sắp xếp và hiểu được mối liên hệ giữa chúng.","Người xưa quan sát Mặt Trăng, Mặt Trời để tính thời gian và làm ra lịch."]],["2. Cách tính thời gian",["Âm lịch: tính theo chu kì Mặt Trăng quay quanh Trái Đất. Dương lịch: tính theo chu kì Trái Đất quay quanh Mặt Trời.","Công lịch là lịch chung của thế giới hiện nay, lấy năm tương truyền Chúa Giê-xu ra đời làm năm 1 Công nguyên (CN); trước đó là trước Công nguyên (TCN).","Đơn vị thời gian: thập kỉ = 10 năm, thế kỉ = 100 năm, thiên niên kỉ = 1 000 năm.","Cách tính khoảng cách: năm TCN và năm CN nằm hai phía của năm 1; muốn biết một năm TCN cách năm hiện tại bao nhiêu năm thì cộng số năm TCN với số năm hiện tại (ví dụ 2000 TCN đến năm 2025 khoảng 4 025 năm)."]]],"nho":["Âm lịch theo Mặt Trăng, dương lịch theo Mặt Trời.","Công lịch lấy năm 1 CN làm mốc; trước đó là TCN.","Thập kỉ 10 năm, thế kỉ 100 năm, thiên niên kỉ 1 000 năm."],"hoi":["Âm lịch và dương lịch khác nhau thế nào?","Năm 208 TCN thuộc thế kỉ nào? Cách năm nay bao nhiêu năm?","Vì sao thế giới cần một thứ lịch chung?"]},{"so":4,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Nguồn gốc loài người","trang":[17,19],"nam":null,"tom":"Loài người có nguồn gốc từ một loài Vượn người sống cách ngày nay khoảng 5–6 triệu năm, trải qua Người tối cổ rồi đến Người tinh khôn. Dấu tích Người tối cổ đã được tìm thấy ở Đông Nam Á và Việt Nam.","muc":[["1. Quá trình tiến hoá từ Vượn người thành người",["Khoảng 5–6 triệu năm trước, ở Đông Phi có loài Vượn người sinh sống.","Khoảng 4 triệu năm trước, một nhánh tiến hoá thành Người tối cổ: đi đứng bằng hai chân, hai chi trước thành tay, biết ghè đẽo công cụ đá.","Khoảng 15 vạn năm trước, Người tối cổ biến đổi thành Người tinh khôn, có cấu tạo cơ thể giống người ngày nay."]],["2. Dấu tích của quá trình chuyển biến ở Đông Nam Á và Việt Nam",["Đông Nam Á là một trong những nơi có dấu tích sớm của loài người, nổi tiếng là hoá thạch Người tối cổ ở đảo Gia-va (In-đô-nê-xi-a).","Ở Việt Nam đã tìm thấy răng hoá thạch Người tối cổ ở Thẩm Khuyên, Thẩm Hai (Lạng Sơn).","Công cụ đá ghè đẽo thô sơ có ở An Khê (Gia Lai), Núi Đọ (Thanh Hoá), Xuân Lộc, An Lộc (Đồng Nai)… chứng tỏ Việt Nam là nơi con người sinh sống từ rất sớm."]]],"nho":["Vượn người (5–6 triệu năm) → Người tối cổ (khoảng 4 triệu năm) → Người tinh khôn (khoảng 15 vạn năm).","Người tối cổ đi bằng hai chân, biết chế tác công cụ đá.","Việt Nam có dấu tích Người tối cổ ở Lạng Sơn, Thanh Hoá, Gia Lai, Đồng Nai."],"hoi":["Trình bày các giai đoạn tiến hoá từ Vượn người thành người.","Những bằng chứng nào cho thấy Việt Nam có con người sinh sống từ rất sớm?","Người tinh khôn khác Người tối cổ ở những điểm nào?"]},{"so":5,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Xã hội nguyên thuỷ","trang":[20,23],"nam":null,"tom":"Xã hội nguyên thuỷ kéo dài hàng triệu năm, trải qua hai giai đoạn: bầy người nguyên thuỷ và công xã thị tộc. Lao động giúp con người và xã hội loài người ngày càng phát triển.","muc":[["1. Các giai đoạn phát triển của xã hội nguyên thuỷ",["Bầy người nguyên thuỷ (thời Người tối cổ): sống thành bầy vài chục người, công cụ thô sơ, dựa vào hái lượm, săn bắt.","Công xã thị tộc (thời Người tinh khôn): gồm những người cùng huyết thống, sống chung, làm chung, hưởng chung; nhiều thị tộc hợp thành bộ lạc."]],["2. Đời sống vật chất, tinh thần và tổ chức xã hội",["Vật chất: từ ghè đẽo đến mài đá, làm cung tên, đồ gốm; biết dùng lửa; từ hái lượm, săn bắt chuyển dần sang trồng trọt, chăn nuôi; sống trong hang động, mái đá rồi dựng lều.","Tinh thần: có tục chôn người chết kèm công cụ, biết làm đồ trang sức, vẽ trên vách hang – thể hiện tín ngưỡng và óc thẩm mĩ.","Ở Việt Nam, di chỉ văn hoá Hoà Bình, Bắc Sơn, Quỳnh Văn, Hạ Long… có nhiều công cụ đá mài, đồ gốm, dấu vết trồng trọt."]],["3. Vai trò của lao động",["Lao động làm đôi tay khéo léo, trí óc phát triển, con người dần hoàn thiện mình.","Nhờ lao động, con người cải thiện đời sống và tổ chức xã hội ngày càng chặt chẽ."]]],"nho":["Hai giai đoạn: bầy người nguyên thuỷ và công xã thị tộc.","Người nguyên thuỷ biết dùng lửa, mài đá, làm gốm, bước đầu trồng trọt, chăn nuôi.","Lao động đóng vai trò quyết định trong sự phát triển của con người."],"hoi":["Nêu đặc điểm của bầy người nguyên thuỷ và công xã thị tộc.","Đời sống tinh thần của người nguyên thuỷ có những biểu hiện nào?","Vì sao nói lao động giúp con người hoàn thiện chính mình?"]},{"so":6,"chuong":"Chương 2. Xã hội nguyên thuỷ","ten":"Sự chuyển biến và phân hoá của xã hội nguyên thuỷ","trang":[24,27],"nam":null,"tom":"Việc phát hiện kim loại làm năng suất lao động tăng, xuất hiện của cải dư thừa và sự phân hoá giàu nghèo, dẫn tới xã hội có giai cấp. Ở Việt Nam, quá trình này thể hiện qua các nền văn hoá Phùng Nguyên – Đồng Đậu – Gò Mun.","muc":[["1. Kim loại và bước tiến của xã hội",["Khoảng 3500 năm TCN, con người biết đúc đồng đỏ, sau đó là đồng thau; khoảng cuối thiên niên kỉ II TCN biết luyện sắt.","Công cụ kim loại giúp khai hoang, mở rộng trồng trọt, làm thêm nghề thủ công; sản phẩm làm ra nhiều hơn, có dư thừa.","Của cải dư thừa bị một số người chiếm làm riêng; xã hội phân hoá giàu – nghèo, gia đình phụ hệ thay cho thị tộc, xã hội có giai cấp ra đời."]],["2. Sự phân hoá không triệt để ở phương Đông",["Cư dân phương Đông sống ven sông lớn, cần làm thuỷ lợi chung nên quan hệ cộng đồng (công xã nông thôn) vẫn được giữ lại.","Vì vậy xã hội có phân hoá nhưng nhiều tàn dư của xã hội nguyên thuỷ còn tồn tại lâu dài."]],["3. Sự tan rã của xã hội nguyên thuỷ ở Việt Nam",["Từ khoảng 4 000 năm trước, cư dân ở Bắc Bộ, Trung Bộ và Nam Bộ đã biết đồ đồng.","Các nền văn hoá Phùng Nguyên – Đồng Đậu – Gò Mun cho thấy nghề luyện kim, trồng lúa nước, làm gốm phát triển; cư dân định cư ven các dòng sông lớn.","Mộ táng có sự chênh lệch đồ chôn theo, phản ánh sự phân hoá trong xã hội."]]],"nho":["Kim loại → năng suất tăng → của cải dư thừa → phân hoá giàu nghèo → xã hội có giai cấp.","Phương Đông phân hoá không triệt để do nhu cầu làm thuỷ lợi chung.","Ở Việt Nam: Phùng Nguyên – Đồng Đậu – Gò Mun."],"hoi":["Kim loại đã làm thay đổi đời sống con người như thế nào?","Vì sao xã hội nguyên thuỷ ở phương Đông phân hoá không triệt để?","Nêu một số nét chính về xã hội Việt Nam thời Phùng Nguyên – Đồng Đậu – Gò Mun."]},{"so":7,"chuong":"Chương 3. Xã hội cổ đại","ten":"Ai Cập và Lưỡng Hà cổ đại","trang":[29,33],"nam":-3200,"tom":"Nhờ phù sa sông Nin, sông Ơ-phrát và Ti-grơ, Ai Cập và Lưỡng Hà sớm hình thành nhà nước từ thiên niên kỉ IV TCN, để lại nhiều thành tựu văn hoá lớn cho nhân loại.","muc":[["1. Điều kiện tự nhiên",["Ai Cập nằm ở Đông Bắc châu Phi, dọc sông Nin; Lưỡng Hà nằm giữa hai con sông Ơ-phrát và Ti-grơ (Tây Á).","Đất phù sa màu mỡ, dễ canh tác; nước sông thuận cho tưới tiêu và đi lại, nhưng cũng gây lũ lụt nên phải làm thuỷ lợi."]],["2. Quá trình thành lập nhà nước",["Ai Cập: các công xã (Nôm) hợp nhất; khoảng năm 3200 TCN, vua Na-mơ (Menes) thống nhất, lập nhà nước; đứng đầu là Pha-ra-ông có quyền tối cao.","Lưỡng Hà: khoảng thiên niên kỉ IV TCN, người Xu-me lập nhiều thành bang; đứng đầu là En-xi; sau này có vương quốc Ba-bi-lon với bộ luật Ham-mu-ra-bi."]],["3. Những thành tựu văn hoá tiêu biểu",["Chữ viết: chữ tượng hình (Ai Cập), chữ hình nêm khắc trên đất sét (Lưỡng Hà).","Toán học: Ai Cập giỏi hình học, tính diện tích; Lưỡng Hà giỏi số học, đếm theo hệ 60.","Lịch và thiên văn: làm ra âm lịch; Ai Cập có lịch 365 ngày.","Kiến trúc: kim tự tháp, tượng Nhân sư (Ai Cập); vườn treo Ba-bi-lon (Lưỡng Hà).","Y học: kĩ thuật ướp xác của người Ai Cập."]]],"nho":["Ai Cập ven sông Nin; Lưỡng Hà giữa sông Ơ-phrát và Ti-grơ.","Nhà nước hình thành từ thiên niên kỉ IV TCN.","Thành tựu: chữ tượng hình, chữ hình nêm, toán học, lịch, kim tự tháp, vườn treo."],"hoi":["Các dòng sông đã ảnh hưởng thế nào đến sự hình thành văn minh Ai Cập và Lưỡng Hà?","Kể tên ba thành tựu văn hoá tiêu biểu của mỗi nền văn minh.","Theo em, thành tựu nào của người Ai Cập, Lưỡng Hà còn được sử dụng đến ngày nay?"]},{"so":8,"chuong":"Chương 3. Xã hội cổ đại","ten":"Ấn Độ cổ đại","trang":[34,38],"nam":-2500,"tom":"Ấn Độ cổ đại hình thành bên lưu vực sông Ấn và sông Hằng, có xã hội phân chia đẳng cấp sâu sắc (chế độ Vác-na) và nhiều thành tựu văn hoá ảnh hưởng rộng ra khu vực, trong đó có Đông Nam Á.","muc":[["1. Điều kiện tự nhiên",["Ấn Độ là một bán đảo ở Nam Á; phía bắc có dãy Hi-ma-lay-a, có hai con sông lớn là sông Ấn và sông Hằng bồi đắp đồng bằng màu mỡ.","Khí hậu có gió mùa; miền nam là cao nguyên Đê-can khô hạn."]],["2. Xã hội Ấn Độ cổ đại",["Khoảng giữa thiên niên kỉ III TCN, người bản địa Đra-vi-đa xây dựng các thành thị ở lưu vực sông Ấn.","Khoảng giữa thiên niên kỉ II TCN, người A-ri-a từ Trung Á tràn vào, lập ra các vương quốc.","Chế độ đẳng cấp Vác-na chia xã hội thành bốn đẳng cấp: Bra-man (tăng lữ), Ksa-tri-a (quý tộc, chiến binh), Vai-si-a (nông dân, thương nhân, thợ thủ công), Su-đra (người lao động nghèo); quy định khắt khe về hôn nhân, nghề nghiệp."]],["3. Những thành tựu văn hoá tiêu biểu",["Tôn giáo: nơi ra đời của đạo Bà La Môn (sau là Hin-đu) và Phật giáo.","Chữ viết: chữ Phạn; văn học với các sử thi Ma-ha-bha-ra-ta, Ra-ma-y-a-na.","Toán học: sáng tạo hệ chữ số, trong đó có số 0.","Kiến trúc: tháp Phật, chùa hang, cột đá A-sô-ca."]]],"nho":["Văn minh Ấn Độ gắn với sông Ấn, sông Hằng.","Chế độ Vác-na với bốn đẳng cấp.","Thành tựu: Phật giáo, Hin-đu giáo, chữ Phạn, sử thi, chữ số và số 0."],"hoi":["Trình bày chế độ đẳng cấp Vác-na của Ấn Độ cổ đại.","Nêu các thành tựu văn hoá tiêu biểu của Ấn Độ cổ đại.","Thành tựu nào của Ấn Độ cổ đại có ảnh hưởng đến Việt Nam?"]},{"so":9,"chuong":"Chương 3. Xã hội cổ đại","ten":"Trung Quốc cổ đại","trang":[39,43],"nam":-221,"tom":"Văn minh Trung Quốc hình thành ở lưu vực Hoàng Hà và Trường Giang. Năm 221 TCN, Tần Thuỷ Hoàng thống nhất Trung Quốc; các triều đại tiếp theo để lại nhiều thành tựu lớn.","muc":[["1. Điều kiện tự nhiên",["Hoàng Hà và Trường Giang bồi đắp những đồng bằng rộng lớn, màu mỡ, thuận lợi cho trồng trọt.","Lũ lụt thường xuyên khiến cư dân phải đắp đê, làm thuỷ lợi."]],["2. Quá trình thống nhất và xác lập chế độ phong kiến",["Từ thời Hạ, Thương, Chu, rồi đến thời Xuân Thu – Chiến Quốc với nhiều nước nhỏ đánh chiếm lẫn nhau.","Năm 221 TCN, nhà Tần thống nhất Trung Quốc; Tần Thuỷ Hoàng thống nhất đo lường, tiền tệ, chữ viết, xây dựng chế độ quân chủ chuyên chế.","Xã hội hình thành hai giai cấp chính: địa chủ và nông dân lĩnh canh; chế độ phong kiến được xác lập."]],["3. Từ đế chế Hán đến Tuỳ",["Nhà Hán (206 TCN – 220) mở rộng lãnh thổ, kinh tế phát triển.","Sau đó là thời kì chia cắt Tam quốc, Tấn, Nam – Bắc triều; năm 589 nhà Tuỳ thống nhất lại đất nước."]],["4. Những thành tựu văn hoá tiêu biểu",["Tư tưởng: Nho giáo (Khổng Tử), Đạo giáo (Lão Tử).","Chữ viết: từ chữ giáp cốt đến chữ Hán; sử học có Sử kí của Tư Mã Thiên.","Kĩ thuật: giấy, la bàn, thuốc súng, kĩ thuật in.","Công trình: Vạn Lí Trường Thành."]]],"nho":["Văn minh Trung Quốc gắn với Hoàng Hà, Trường Giang.","221 TCN: nhà Tần thống nhất Trung Quốc.","Thành tựu: Nho giáo, chữ Hán, Sử kí, giấy, la bàn, thuốc súng, Vạn Lí Trường Thành."],"hoi":["Tần Thuỷ Hoàng đã làm gì để củng cố sự thống nhất Trung Quốc?","Xã hội Trung Quốc thời phong kiến có những giai cấp nào?","Kể tên bốn phát minh kĩ thuật nổi tiếng của người Trung Quốc."]},{"so":10,"chuong":"Chương 3. Xã hội cổ đại","ten":"Hy Lạp và La Mã cổ đại","trang":[44,49],"nam":null,"tom":"Hy Lạp và La Mã hình thành bên bờ Địa Trung Hải, phát triển mạnh thương nghiệp, hàng hải và để lại tổ chức nhà nước dân chủ chủ nô, đế chế cùng nhiều thành tựu văn hoá rực rỡ.","muc":[["1. Điều kiện tự nhiên",["Hy Lạp gồm bán đảo Ban-căng, nhiều đảo nhỏ; La Mã ở bán đảo I-ta-li-a.","Đất ít, khô cứng, khó trồng lúa; bù lại có bờ biển khúc khuỷu, nhiều vịnh, nhiều khoáng sản → phát triển thủ công nghiệp, thương nghiệp đường biển."]],["2. Tổ chức nhà nước",["Hy Lạp gồm nhiều thành bang độc lập; tiêu biểu là A-ten với nhà nước dân chủ chủ nô: Đại hội nhân dân, Hội đồng 500 người… nhưng phụ nữ, kiều dân và nô lệ không có quyền công dân.","La Mã từ cộng hoà chuyển sang đế chế; quyền lực tập trung trong tay hoàng đế, lãnh thổ bao quanh Địa Trung Hải.","Nô lệ là lực lượng lao động chính trong xã hội."]],["3. Những thành tựu văn hoá tiêu biểu",["Chữ viết: hệ chữ cái La-tinh, chữ số La Mã.","Khoa học: các nhà toán học như Py-ta-go, Ta-lét, Ác-si-mét…","Văn học, sử học: sử thi I-li-át, Ô-đi-xê của Hô-me.","Kiến trúc, điêu khắc: đền Pác-tê-nông, đấu trường Cô-li-dê, tượng thần Vệ nữ Mi-lô.","Lịch: người La Mã làm ra dương lịch, nền tảng của lịch dùng ngày nay."]]],"nho":["Biển là điều kiện thuận lợi để Hy Lạp, La Mã phát triển thương nghiệp.","A-ten: dân chủ chủ nô; La Mã: từ cộng hoà đến đế chế.","Thành tựu: chữ cái La-tinh, toán học, sử thi, đền Pác-tê-nông, đấu trường Cô-li-dê, dương lịch."],"hoi":["Điều kiện tự nhiên ảnh hưởng thế nào đến kinh tế Hy Lạp, La Mã?","Nhà nước dân chủ chủ nô ở A-ten được tổ chức như thế nào? Có hạn chế gì?","Thành tựu nào của Hy Lạp, La Mã vẫn được dùng ngày nay?"]},{"so":11,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Các quốc gia sơ kì ở Đông Nam Á","trang":[51,53],"nam":null,"tom":"Từ những thế kỉ trước và sau Công nguyên, trên cơ sở kinh tế nông nghiệp lúa nước, buôn bán và tiếp thu văn hoá bên ngoài, ở Đông Nam Á lần lượt ra đời các quốc gia sơ kì.","muc":[["1. Điều kiện hình thành",["Đông Nam Á có khí hậu gió mùa, nhiều sông lớn, đồng bằng màu mỡ, thuận lợi trồng lúa nước.","Nằm trên đường giao thương giữa Ấn Độ và Trung Quốc nên sớm có buôn bán, tiếp xúc văn hoá.","Kĩ thuật luyện kim (đồng, sắt) phát triển, xã hội phân hoá."]],["2. Sự xuất hiện các quốc gia sơ kì",["Khoảng thế kỉ VII TCN – thế kỉ VII, xuất hiện nhiều quốc gia sơ kì: Văn Lang – Âu Lạc, Chăm-pa, Phù Nam (trên lãnh thổ Việt Nam), các quốc gia ở hạ lưu sông Chao Phray-a, trên các đảo Gia-va, Xu-ma-tơ-ra…","Các quốc gia này còn nhỏ, chưa có sự thống nhất lớn; kinh tế dựa vào nông nghiệp và thương mại đường biển."]]],"nho":["Cơ sở: lúa nước, luyện kim, giao thương biển.","Các quốc gia sơ kì tiêu biểu: Văn Lang – Âu Lạc, Chăm-pa, Phù Nam."],"hoi":["Những điều kiện nào dẫn tới sự ra đời các quốc gia sơ kì ở Đông Nam Á?","Kể tên một số quốc gia sơ kì ở Đông Nam Á và ở Việt Nam."]},{"so":12,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Sự hình thành và bước đầu phát triển của các vương quốc phong kiến ở Đông Nam Á (từ thế kỉ VII đến thế kỉ X)","trang":[54,55],"nam":null,"tom":"Từ thế kỉ VII đến thế kỉ X, ở Đông Nam Á hình thành các vương quốc phong kiến, nổi bật là Sri Vi-giay-a ở hải đảo; kinh tế thương mại biển phát triển mạnh.","muc":[["1. Sự hình thành các vương quốc phong kiến",["Các vương quốc thường lấy một tộc người đông và phát triển nhất làm nòng cốt: Chân Lạp của người Khơ-me (thay thế Phù Nam), Sri Kse-tra của người Pyu, Đva-ra-va-ti của người Môn (lưu vực sông Chao Phray-a), Sri Vi-giay-a ở đảo Xu-ma-tơ-ra…","Sri Vi-giay-a nằm ở vùng eo biển Ma-lắc-ca, trở thành cường quốc thương mại biển."]],["2. Sự phát triển kinh tế",["Kinh tế nông nghiệp trồng lúa vẫn giữ vai trò chính ở vùng lục địa.","Thương mại biển phát triển; nhiều thương cảng sầm uất, buôn bán với Ấn Độ, Trung Quốc, A-rập."]]],"nho":["Thế kỉ VII – X: các vương quốc phong kiến hình thành ở Đông Nam Á.","Sri Vi-giay-a là cường quốc thương mại biển."],"hoi":["Kể tên các vương quốc phong kiến ở Đông Nam Á từ thế kỉ VII đến thế kỉ X.","Vì sao thương mại biển ở Đông Nam Á phát triển mạnh?"]},{"so":13,"chuong":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","ten":"Giao lưu văn hoá ở Đông Nam Á từ đầu Công nguyên đến thế kỉ X","trang":[56,58],"nam":null,"tom":"Qua buôn bán và truyền giáo, cư dân Đông Nam Á tiếp thu văn hoá Ấn Độ, Trung Quốc một cách chọn lọc, kết hợp với văn hoá bản địa để tạo nên bản sắc riêng.","muc":[["1. Tiếp thu văn hoá Ấn Độ",["Tôn giáo: Phật giáo, Hin-đu giáo theo các thương nhân, tăng lữ vào Đông Nam Á.","Chữ viết: nhiều dân tộc dựa vào chữ Phạn để sáng tạo chữ viết riêng.","Văn học, kiến trúc: sử thi Ra-ma-y-a-na lan rộng; đền tháp mang phong cách Ấn Độ."]],["2. Tiếp thu văn hoá Trung Quốc",["Ảnh hưởng rõ nhất ở Việt Nam: chữ Hán, Nho giáo, Đạo giáo, cách tổ chức nhà nước.","Cư dân Đông Nam Á tiếp thu có chọn lọc, giữ những yếu tố phù hợp và giữ gìn văn hoá bản địa."]]],"nho":["Đông Nam Á tiếp thu văn hoá Ấn Độ và Trung Quốc qua buôn bán, truyền giáo.","Tiếp thu có chọn lọc, kết hợp với văn hoá bản địa."],"hoi":["Văn hoá Ấn Độ ảnh hưởng đến Đông Nam Á ở những lĩnh vực nào?","Vì sao nói cư dân Đông Nam Á tiếp thu văn hoá bên ngoài có chọn lọc?"]},{"so":14,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Nhà nước Văn Lang, Âu Lạc","trang":[60,64],"nam":-208,"tom":"Khoảng thế kỉ VII TCN, nhà nước Văn Lang ra đời ở lưu vực sông Hồng, sông Mã, sông Cả. Khoảng năm 208 TCN, Thục Phán lập nước Âu Lạc, đóng đô ở Cổ Loa.","muc":[["1. Sự ra đời nhà nước Văn Lang",["Cư dân Việt cổ định cư ven các dòng sông lớn, làm nông nghiệp lúa nước, cần trị thuỷ và chống ngoại xâm, nên các bộ lạc liên kết lại.","Khoảng thế kỉ VII TCN, thủ lĩnh bộ lạc Văn Lang hợp nhất các bộ lạc, xưng Hùng Vương, đóng đô ở Phong Châu (Phú Thọ ngày nay), đặt tên nước là Văn Lang.","Tổ chức nhà nước còn đơn giản: Hùng Vương – Lạc hầu, Lạc tướng – Bồ chính ở các chiềng, chạ."]],["2. Nhà nước Âu Lạc",["Cuối thế kỉ III TCN, người Âu Việt và Lạc Việt cùng kháng chiến chống quân Tần.","Khoảng năm 208 TCN, Thục Phán lên ngôi, hiệu An Dương Vương, lập nước Âu Lạc, xây thành Cổ Loa; quân đội mạnh, có nỏ bắn nhiều phát.","Năm 179 TCN, Triệu Đà đánh chiếm Âu Lạc; nước ta rơi vào thời kì Bắc thuộc."]],["3. Đời sống của cư dân Văn Lang, Âu Lạc",["Vật chất: trồng lúa nước, chăn nuôi, đánh cá; đúc đồng (trống đồng Đông Sơn), làm gốm; ở nhà sàn, ăn cơm, rau, cá; nam đóng khố, nữ mặc váy.","Tinh thần: thờ cúng tổ tiên, thờ thần tự nhiên; có tục nhuộm răng, ăn trầu, xăm mình; lễ hội đua thuyền, giã gạo."]]],"nho":["Thế kỉ VII TCN: nhà nước Văn Lang, kinh đô Phong Châu.","Khoảng 208 TCN: An Dương Vương lập Âu Lạc, xây thành Cổ Loa.","Trống đồng Đông Sơn tiêu biểu cho văn minh Văn Lang – Âu Lạc."],"hoi":["Vì sao nhà nước Văn Lang ra đời?","Thành Cổ Loa và nỏ thần cho thấy điều gì về nhà nước Âu Lạc?","Những phong tục nào của cư dân Văn Lang, Âu Lạc còn được giữ đến ngày nay?"]},{"so":15,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Chính sách cai trị của các triều đại phong kiến phương Bắc và sự chuyển biến của xã hội Âu Lạc","trang":[65,69],"nam":null,"tom":"Hơn một nghìn năm Bắc thuộc, các triều đại phương Bắc chia nước ta thành quận huyện, bóc lột nặng nề và tìm cách đồng hoá. Dù vậy, kinh tế, xã hội Âu Lạc vẫn có những chuyển biến.","muc":[["1. Chính sách cai trị",["Chính trị: chia Âu Lạc thành các quận, huyện, sáp nhập vào lãnh thổ phương Bắc; đặt quan lại cai trị đến cấp huyện.","Kinh tế: bắt nộp tô thuế nặng, cống nạp sản vật quý; nắm độc quyền muối, sắt.","Văn hoá: truyền bá chữ Hán, Nho giáo, bắt theo phong tục người Hán nhằm đồng hoá dân ta."]],["2. Chuyển biến về kinh tế",["Nông nghiệp: dùng cày sắt, trâu bò kéo; làm thuỷ lợi, trồng lúa hai vụ.","Thủ công: rèn sắt, làm gốm, dệt vải phát triển; một số nghề mới như làm giấy, thuỷ tinh.","Thương mại: một số trung tâm buôn bán như Luy Lâu."]],["3. Chuyển biến về xã hội",["Xã hội phân hoá sâu sắc; quan lại đô hộ, địa chủ người Hán và hào trưởng người Việt.","Nông dân bị bóc lột nặng nề, mâu thuẫn với chính quyền đô hộ ngày càng gay gắt."]]],"nho":["Bắc thuộc: chia quận huyện, bóc lột nặng, đồng hoá văn hoá.","Kinh tế vẫn phát triển: cày sắt, trâu bò, nghề thủ công mới.","Mâu thuẫn dân tộc gay gắt dẫn tới các cuộc khởi nghĩa."],"hoi":["Nêu những chính sách cai trị của phong kiến phương Bắc về chính trị, kinh tế, văn hoá.","Kinh tế Âu Lạc thời Bắc thuộc có những chuyển biến gì?","Vì sao các cuộc khởi nghĩa liên tục nổ ra trong thời Bắc thuộc?"]},{"so":16,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Các cuộc khởi nghĩa tiêu biểu giành độc lập trước thế kỉ X","trang":[70,77],"nam":40,"tom":"Trong hơn một nghìn năm Bắc thuộc, người Việt liên tục vùng lên. Tiêu biểu là các cuộc khởi nghĩa Hai Bà Trưng, Bà Triệu, Lý Bí, Mai Thúc Loan, Phùng Hưng.","muc":[["1. Khởi nghĩa Hai Bà Trưng (năm 40)",["Nguyên nhân: căm thù ách đô hộ của nhà Hán, Thái thú Tô Định tham lam, tàn bạo.","Mùa xuân năm 40, Trưng Trắc, Trưng Nhị dựng cờ ở Hát Môn, nghĩa quân chiếm Mê Linh, Cổ Loa, Luy Lâu; Trưng Trắc lên ngôi vua.","Năm 42–43, nhà Hán đem quân sang đàn áp; cuộc khởi nghĩa thất bại nhưng khẳng định ý chí độc lập."]],["2. Khởi nghĩa Bà Triệu (năm 248)",["Bà Triệu (Triệu Thị Trinh) cùng anh khởi nghĩa ở núi Nưa (Thanh Hoá) chống ách đô hộ của nhà Ngô.","Cuộc khởi nghĩa làm rung động chính quyền đô hộ, sau đó bị đàn áp."]],["3. Khởi nghĩa Lý Bí và nước Vạn Xuân (542–602)",["Năm 542, Lý Bí khởi nghĩa chống nhà Lương, chiếm thành Long Biên.","Năm 544, Lý Bí lên ngôi, xưng Lý Nam Đế, đặt tên nước là Vạn Xuân.","Triệu Quang Phục tiếp tục kháng chiến ở đầm Dạ Trạch; nước Vạn Xuân tồn tại đến năm 602."]],["4. Khởi nghĩa Mai Thúc Loan và Phùng Hưng",["Đầu thế kỉ VIII, Mai Thúc Loan khởi nghĩa ở Hoan Châu, xưng hoàng đế (Mai Hắc Đế), xây thành Vạn An.","Khoảng năm 776, Phùng Hưng khởi nghĩa ở Đường Lâm, chiếm phủ thành Tống Bình; nhân dân tôn ông là Bố Cái Đại Vương."]]],"nho":["Năm 40: Hai Bà Trưng; năm 248: Bà Triệu; năm 542: Lý Bí, năm 544 lập nước Vạn Xuân.","Thế kỉ VIII: Mai Thúc Loan, Phùng Hưng.","Các cuộc khởi nghĩa thể hiện ý chí độc lập bền bỉ của dân tộc."],"hoi":["Trình bày nguyên nhân, diễn biến chính và ý nghĩa của khởi nghĩa Hai Bà Trưng.","Việc Lý Bí đặt tên nước là Vạn Xuân có ý nghĩa gì?","Lập bảng các cuộc khởi nghĩa tiêu biểu: thời gian, người lãnh đạo, kết quả."]},{"so":17,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Cuộc đấu tranh bảo tồn và phát triển văn hoá dân tộc của người Việt","trang":[78,79],"nam":null,"tom":"Dù bị đô hộ lâu dài, người Việt vẫn giữ được tiếng nói, phong tục, tín ngưỡng của mình, đồng thời tiếp thu chọn lọc văn hoá Trung Hoa để làm giàu văn hoá dân tộc.","muc":[["1. Giữ gìn văn hoá truyền thống",["Người Việt vẫn nói tiếng Việt; giữ tục thờ cúng tổ tiên, thờ các anh hùng, thờ thần tự nhiên.","Phong tục nhuộm răng đen, ăn trầu, làm bánh chưng, bánh giầy được duy trì trong làng xã.","Làng xã là nơi lưu giữ và bảo vệ văn hoá dân tộc."]],["2. Tiếp thu có chọn lọc văn hoá Trung Hoa",["Học chữ Hán nhưng đọc theo cách đọc của người Việt.","Tiếp thu Nho giáo, Phật giáo, Đạo giáo một cách phù hợp, kết hợp với tín ngưỡng dân gian.","Học kĩ thuật làm giấy, làm thuỷ tinh… để phát triển kinh tế."]]],"nho":["Người Việt giữ được tiếng nói và phong tục truyền thống.","Tiếp thu văn hoá Trung Hoa có chọn lọc, không bị đồng hoá."],"hoi":["Những phong tục nào của người Việt vẫn được giữ gìn trong thời Bắc thuộc?","Vì sao người Việt không bị đồng hoá sau hơn một nghìn năm Bắc thuộc?"]},{"so":18,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Bước ngoặt lịch sử đầu thế kỉ X","trang":[80,85],"nam":938,"tom":"Đầu thế kỉ X, họ Khúc giành quyền tự chủ; Dương Đình Nghệ đánh bại quân Nam Hán lần thứ nhất. Năm 938, Ngô Quyền lãnh đạo chiến thắng Bạch Đằng, chấm dứt hơn một nghìn năm Bắc thuộc.","muc":[["1. Họ Khúc dựng quyền tự chủ",["Năm 905, nhân nhà Đường suy yếu, Khúc Thừa Dụ chiếm thành Đại La, tự xưng Tiết độ sứ, dựng quyền tự chủ.","Khúc Hạo tiến hành nhiều cải cách: định lại thuế, đặt lại các đơn vị hành chính, chăm lo đời sống nhân dân."]],["2. Dương Đình Nghệ chống quân Nam Hán",["Năm 930, quân Nam Hán chiếm nước ta. Năm 931, Dương Đình Nghệ đem quân từ Ái Châu đánh tan quân Nam Hán, giữ vững quyền tự chủ.","Năm 937, Dương Đình Nghệ bị Kiều Công Tiễn giết hại; Kiều Công Tiễn cầu cứu nhà Nam Hán."]],["3. Ngô Quyền và chiến thắng Bạch Đằng năm 938",["Ngô Quyền tiến quân ra Bắc, giết Kiều Công Tiễn, chuẩn bị đánh quân Nam Hán.","Ông cho đóng cọc gỗ đầu bịt sắt ở cửa sông Bạch Đằng, lợi dụng thuỷ triều nhử địch vào trận địa cọc.","Khi nước triều rút, quân ta đánh mạnh; thuyền giặc va vào cọc, đắm vỡ; Lưu Hoằng Tháo tử trận.","Ý nghĩa: chấm dứt hơn một nghìn năm Bắc thuộc, mở ra thời kì độc lập lâu dài của dân tộc."]]],"nho":["905: Khúc Thừa Dụ dựng quyền tự chủ.","931: Dương Đình Nghệ đánh đuổi quân Nam Hán.","938: Ngô Quyền chiến thắng Bạch Đằng, kết thúc thời Bắc thuộc."],"hoi":["Vì sao nói họ Khúc đặt nền móng cho nền độc lập?","Trình bày kế hoạch đánh giặc độc đáo của Ngô Quyền trên sông Bạch Đằng.","Chiến thắng Bạch Đằng năm 938 có ý nghĩa như thế nào?"]},{"so":19,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Vương quốc Chăm-pa từ thế kỉ II đến thế kỉ X","trang":[86,90],"nam":192,"tom":"Cuối thế kỉ II, Khu Liên lập nước Lâm Ấp ở vùng Tượng Lâm, về sau gọi là Chăm-pa. Vương quốc này có nền kinh tế biển phát triển và văn hoá đặc sắc với những đền tháp Chăm.","muc":[["1. Sự thành lập và phát triển",["Năm 192, nhân dân huyện Tượng Lâm dưới sự lãnh đạo của Khu Liên nổi dậy, lập nước Lâm Ấp; đến thế kỉ VI đổi tên là Chăm-pa.","Lãnh thổ trải dài ven biển miền Trung Việt Nam ngày nay; các kinh đô như Sin-ha-pu-ra (Trà Kiệu), In-đra-pu-ra (Đồng Dương)."]],["2. Kinh tế và xã hội",["Trồng lúa nước, làm ruộng bậc thang; khai thác lâm sản quý như trầm hương.","Đánh cá, buôn bán đường biển phát triển; nhiều thương cảng sầm uất.","Xã hội gồm vua, quý tộc, nông dân tự do và nô lệ."]],["3. Văn hoá",["Sáng tạo chữ viết riêng dựa trên chữ Phạn.","Theo Hin-đu giáo và Phật giáo; xây dựng nhiều đền tháp, tiêu biểu là khu đền tháp Mỹ Sơn (Quảng Nam).","Nghệ thuật điêu khắc tinh xảo; tục hoả táng người chết."]]],"nho":["192: Khu Liên lập nước Lâm Ấp, sau là Chăm-pa.","Kinh tế lúa nước, buôn bán biển; văn hoá chịu ảnh hưởng Ấn Độ.","Khu đền tháp Mỹ Sơn tiêu biểu cho văn hoá Chăm-pa."],"hoi":["Trình bày sự ra đời của vương quốc Chăm-pa.","Nêu những nét chính về kinh tế, văn hoá Chăm-pa.","Ngày nay còn những di sản nào của văn hoá Chăm-pa?"]},{"so":20,"chuong":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","ten":"Vương quốc Phù Nam","trang":[91,94],"nam":null,"tom":"Khoảng thế kỉ I, vương quốc Phù Nam hình thành ở vùng châu thổ sông Cửu Long, phát triển mạnh nhờ thương mại biển với trung tâm là thương cảng Óc Eo, đến thế kỉ VII thì suy yếu.","muc":[["1. Sự thành lập, phát triển và suy vong",["Khoảng thế kỉ I, Phù Nam ra đời ở vùng đồng bằng châu thổ sông Cửu Long.","Thế kỉ III – V là thời kì phát triển mạnh, mở rộng ảnh hưởng ra nhiều vùng xung quanh.","Cuối thế kỉ VI, Phù Nam suy yếu và bị Chân Lạp thôn tính vào thế kỉ VII."]],["2. Kinh tế, xã hội và văn hoá",["Trồng lúa nước, làm thủ công (gốm, kim hoàn), buôn bán đường biển rất phát triển.","Thương cảng Óc Eo (An Giang) là nơi buôn bán với Ấn Độ, Trung Quốc, Địa Trung Hải.","Cư dân ở nhà sàn, theo Hin-đu giáo và Phật giáo; văn hoá Óc Eo để lại nhiều di vật quý."]]],"nho":["Phù Nam hình thành khoảng thế kỉ I ở châu thổ sông Cửu Long.","Óc Eo là thương cảng quốc tế quan trọng.","Thế kỉ VII, Phù Nam bị Chân Lạp thôn tính."],"hoi":["Trình bày sự hình thành và phát triển của vương quốc Phù Nam.","Vì sao thương cảng Óc Eo trở thành trung tâm buôn bán quan trọng?","Kể tên một số di vật của văn hoá Óc Eo mà em biết."]}]},"7":{"sach":"Lịch sử và Địa lí 7 (bộ Kết nối tri thức với cuộc sống, NXB Giáo dục Việt Nam), phần Lịch sử, tr. 7–94 và hai chủ đề chung tr. 166–174","ghi_chu":"Nội dung do Việt Sử biên soạn lại bằng lời văn riêng theo mạch bài học của SGK; không chép nguyên văn, không dùng hình ảnh của sách. Học sinh mở SGK theo số trang để xem tư liệu, hình và hoạt động.","bai":[{"so":1,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Quá trình hình thành và phát triển của chế độ phong kiến ở Tây Âu","trang":[9,13],"nam":null,"tom":"Sau khi Đế quốc Tây La Mã sụp đổ (năm 476), các vương quốc của người Giéc-man hình thành, chế độ phong kiến Tây Âu ra đời với các lãnh địa, rồi thành thị trung đại xuất hiện, kinh tế hàng hoá phát triển.","muc":[["1. Sự hình thành chế độ phong kiến ở Tây Âu",["Cuối thế kỉ V, người Giéc-man tràn vào, Đế quốc Tây La Mã diệt vong (476); nhiều vương quốc mới được lập ra.","Người Giéc-man chiếm ruộng đất của chủ nô cũ, phong tước vị cho nhau; hình thành hai giai cấp lãnh chúa và nông nô."]],["2. Lãnh địa phong kiến và quan hệ trong xã hội",["Lãnh địa là vùng đất do lãnh chúa làm chủ, có lâu đài, nhà thờ, ruộng đất, như một vương quốc thu nhỏ, tự cấp tự túc.","Nông nô nhận ruộng canh tác, nộp tô thuế và chịu nhiều nghĩa vụ; lãnh chúa sống sung sướng nhờ bóc lột nông nô."]],["3. Thành thị trung đại và Thiên Chúa giáo",["Từ thế kỉ XI, sản xuất phát triển, thợ thủ công và thương nhân tụ tập ở nơi đông người, lập ra thành thị.","Thành thị thúc đẩy kinh tế hàng hoá, phá vỡ tính tự cấp tự túc của lãnh địa; tầng lớp thị dân ra đời.","Thiên Chúa giáo có vai trò lớn trong đời sống tinh thần và chính trị; Giáo hội là thế lực phong kiến lớn."]]],"nho":["476: Tây La Mã diệt vong; chế độ phong kiến Tây Âu hình thành.","Lãnh chúa và nông nô là hai giai cấp chính; lãnh địa là đơn vị kinh tế tự cấp tự túc.","Thành thị trung đại thúc đẩy kinh tế hàng hoá."],"hoi":["Chế độ phong kiến Tây Âu hình thành như thế nào?","Mô tả đời sống trong một lãnh địa phong kiến.","Thành thị trung đại có vai trò gì đối với xã hội Tây Âu?"]},{"so":2,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Các cuộc phát kiến địa lí và sự hình thành quan hệ sản xuất tư bản chủ nghĩa ở Tây Âu","trang":[14,17],"nam":1492,"tom":"Cuối thế kỉ XV – đầu thế kỉ XVI, những chuyến đi biển lớn tìm ra đường sang phương Đông, châu Mỹ và vòng quanh Trái Đất, đem lại nguồn vốn và thị trường cho quan hệ sản xuất tư bản chủ nghĩa ở Tây Âu.","muc":[["1. Các cuộc phát kiến địa lí",["Nguyên nhân: nhu cầu vàng bạc, hương liệu, thị trường; con đường buôn bán qua Tây Á bị chặn; kĩ thuật hàng hải tiến bộ (la bàn, tàu ca-ra-ven, hiểu biết về địa lí).","B. Đi-a-xơ vòng qua cực nam châu Phi (1487); C. Cô-lôm-bô đến châu Mỹ (1492); Va-xcô đơ Ga-ma đến Ấn Độ bằng đường biển (1497–1498); Ph. Ma-gien-lan thực hiện chuyến đi vòng quanh Trái Đất (1519–1522).","Hệ quả: mở ra những con đường mới, đem về nhiều vàng bạc, nguyên liệu, mở rộng thị trường; nhưng cũng mở đầu quá trình xâm chiếm thuộc địa, buôn bán nô lệ."]],["2. Sự hình thành quan hệ sản xuất tư bản chủ nghĩa",["Quý tộc, thương nhân tích luỹ vốn bằng cướp bóc thuộc địa, buôn bán; đuổi nông dân khỏi ruộng đất để có nhân công.","Xuất hiện công trường thủ công, công ti thương mại, đồn điền.","Xã hội hình thành hai giai cấp mới: tư sản (chủ xưởng, chủ đồn điền) và vô sản (người làm thuê)."]]],"nho":["1487 Đi-a-xơ; 1492 Cô-lôm-bô; 1497–1498 Va-xcô đơ Ga-ma; 1519–1522 Ma-gien-lan.","Phát kiến địa lí đem lại vốn, thị trường nhưng mở đầu thời kì xâm chiếm thuộc địa.","Giai cấp tư sản và vô sản hình thành."],"hoi":["Vì sao người châu Âu tiến hành các cuộc phát kiến địa lí?","Trình bày hệ quả tích cực và tiêu cực của các cuộc phát kiến địa lí.","Quan hệ sản xuất tư bản chủ nghĩa hình thành ở Tây Âu như thế nào?"]},{"so":3,"chuong":"Chương 1. Tây Âu từ thế kỉ V đến nửa đầu thế kỉ XVI","ten":"Phong trào Văn hoá Phục hưng và Cải cách tôn giáo","trang":[18,22],"nam":1517,"tom":"Từ thế kỉ XIV ở I-ta-li-a, phong trào Văn hoá Phục hưng đề cao con người và khoa học; đầu thế kỉ XVI, phong trào Cải cách tôn giáo bùng nổ, đòi xoá bỏ những lạc hậu của Giáo hội Thiên Chúa.","muc":[["1. Phong trào Văn hoá Phục hưng",["Bắt đầu ở I-ta-li-a (thế kỉ XIV), lan ra nhiều nước Tây Âu; giai cấp tư sản muốn có hệ tư tưởng riêng, chống lại sự kìm hãm của Giáo hội.","Thành tựu: hội hoạ, điêu khắc của Lê-ô-na-đô đa Vin-xi, Mi-ken-lăng-giơ, Ra-pha-en; văn học của Sếch-xpia, Xéc-van-téc; khoa học của Cô-péc-ních, Ga-li-lê.","Ý nghĩa: đề cao giá trị con người, khoa học, mở đường cho văn hoá châu Âu phát triển."]],["2. Phong trào Cải cách tôn giáo",["Nguyên nhân: Giáo hội ngày càng giàu có, sa đoạ, cản trở sự phát triển của giai cấp tư sản.","Năm 1517, M. Lu-thơ ở Đức công bố luận cương phê phán Giáo hội; sau đó Can-vanh ở Thuỵ Sĩ tiếp tục cải cách.","Nội dung: phủ nhận vai trò thống trị của Giáo hội và Giáo hoàng, đòi bỏ các lễ nghi tốn kém, quay về giáo lí nguyên thuỷ.","Tác động: Thiên Chúa giáo chia thành Cựu giáo và Tân giáo; thúc đẩy cuộc đấu tranh chống phong kiến."]]],"nho":["Phục hưng: bắt đầu ở I-ta-li-a, đề cao con người và khoa học.","Lê-ô-na-đô đa Vin-xi, Sếch-xpia, Cô-péc-ních là những đại diện tiêu biểu.","1517: Lu-thơ khởi đầu Cải cách tôn giáo."],"hoi":["Nêu một số thành tựu tiêu biểu của phong trào Văn hoá Phục hưng.","Phong trào Văn hoá Phục hưng có ý nghĩa gì với xã hội Tây Âu?","Trình bày nguyên nhân và tác động của phong trào Cải cách tôn giáo."]},{"so":4,"chuong":"Chương 2. Trung Quốc và Ấn Độ thời trung đại","ten":"Trung Quốc từ thế kỉ III trước Công nguyên đến giữa thế kỉ XIX","trang":[24,28],"nam":618,"tom":"Từ nhà Tần đến nhà Thanh, chế độ phong kiến Trung Quốc hình thành, phát triển thịnh đạt dưới thời Đường và có mầm mống kinh tế tư bản thời Minh – Thanh, để lại nhiều thành tựu văn hoá lớn.","muc":[["1. Sơ lược tiến trình lịch sử",["Năm 221 TCN, nhà Tần thống nhất Trung Quốc; tiếp theo là Hán, Tuỳ, Đường, Tống, Nguyên, Minh, Thanh.","Chế độ phong kiến được xác lập với hai giai cấp chính: địa chủ và nông dân lĩnh canh."]],["2. Trung Quốc thời Đường",["Nhà Đường (618–907) là thời thịnh trị: bộ máy nhà nước hoàn thiện, tuyển quan lại bằng thi cử.","Kinh tế phát triển nhờ chính sách quân điền, giảm thuế; thủ công, thương nghiệp phát đạt, con đường tơ lụa nhộn nhịp.","Lãnh thổ mở rộng; nhà Đường tăng cường chiến tranh xâm lược bên ngoài."]],["3. Kinh tế thời Minh – Thanh",["Nông nghiệp tiến bộ, thủ công nghiệp có nhiều xưởng lớn thuê nhân công; buôn bán trong và ngoài nước mở rộng.","Xuất hiện mầm mống quan hệ sản xuất tư bản chủ nghĩa."]],["4. Một số thành tựu văn hoá tiêu biểu",["Tư tưởng: Nho giáo giữ vai trò chính thống; Phật giáo phát triển mạnh.","Văn học: thơ Đường (Lý Bạch, Đỗ Phủ, Bạch Cư Dị); tiểu thuyết Tam quốc diễn nghĩa, Thuỷ hử, Tây du kí, Hồng lâu mộng.","Sử học: Sử kí của Tư Mã Thiên và các bộ sử của triều đình.","Kiến trúc, kĩ thuật: Vạn Lí Trường Thành, Cố Cung; giấy, la bàn, thuốc súng, kĩ thuật in."]]],"nho":["Nhà Đường (618–907): thời thịnh trị của phong kiến Trung Quốc.","Thời Minh – Thanh xuất hiện mầm mống tư bản chủ nghĩa.","Thơ Đường, tiểu thuyết Minh – Thanh, bốn phát minh kĩ thuật."],"hoi":["Vì sao nói thời Đường là thời thịnh trị của phong kiến Trung Quốc?","Kinh tế thời Minh – Thanh có điểm gì mới so với thời Đường?","Kể tên một số tác phẩm văn học Trung Quốc thời trung đại mà em biết."]},{"so":5,"chuong":"Chương 2. Trung Quốc và Ấn Độ thời trung đại","ten":"Ấn Độ từ thế kỉ IV đến giữa thế kỉ XIX","trang":[29,33],"nam":null,"tom":"Ấn Độ thời trung đại trải qua ba vương triều lớn: Gúp-ta, Hồi giáo Đê-li và Mô-gôn, với nền văn hoá đặc sắc ảnh hưởng sâu rộng tới Đông Nam Á.","muc":[["1. Các vương triều lớn",["Vương triều Gúp-ta (thế kỉ IV – VI): thống nhất miền Bắc Ấn Độ; kinh tế, văn hoá phát triển, biết luyện sắt (cột sắt không gỉ).","Vương triều Hồi giáo Đê-li (thế kỉ XIII – XVI): người Thổ Nhĩ Kì gốc Trung Á lập ra; truyền bá đạo Hồi; buôn bán với nhiều nước.","Vương triều Mô-gôn (thế kỉ XVI – giữa XIX): người Mông Cổ gốc Trung Á lập ra; thời vua A-cơ-ba đất nước ổn định, phát triển; về sau suy yếu và bị thực dân Anh xâm chiếm."]],["2. Một số thành tựu văn hoá",["Tôn giáo: Hin-đu giáo, Phật giáo, Hồi giáo cùng tồn tại.","Chữ viết, văn học: chữ Phạn hoàn thiện; văn học Hin-đu giáo phong phú.","Kiến trúc, điêu khắc: đền Kha-giu-ra-hô (Hin-đu giáo), lăng Ta-giơ Ma-han (thời Mô-gôn)."]]],"nho":["Ba vương triều: Gúp-ta, Hồi giáo Đê-li, Mô-gôn.","Hin-đu giáo, Phật giáo, Hồi giáo cùng tồn tại.","Lăng Ta-giơ Ma-han là công trình tiêu biểu thời Mô-gôn."],"hoi":["Nêu những nét chính về ba vương triều Gúp-ta, Hồi giáo Đê-li và Mô-gôn.","Kể tên một số thành tựu văn hoá tiêu biểu của Ấn Độ thời trung đại.","Văn hoá Ấn Độ đã ảnh hưởng thế nào đến các nước Đông Nam Á?"]},{"so":6,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Các vương quốc phong kiến Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","trang":[35,38],"nam":null,"tom":"Từ nửa sau thế kỉ X, các vương quốc phong kiến Đông Nam Á bước vào thời kì phát triển thịnh đạt, kinh tế mở rộng giao thương và văn hoá có nhiều thành tựu mang bản sắc riêng.","muc":[["1. Sự phát triển của các vương quốc phong kiến",["Hình thành và phát triển nhiều quốc gia mạnh: Đại Việt, Cam-pu-chia thời Ăng-co, Pa-gan (Mi-an-ma), Su-khô-thay rồi A-du-thay-a (Thái Lan), Lan Xang (Lào), Ma-giắc-pa-hít (In-đô-nê-xi-a), Ma-lắc-ca…","Kinh tế nông nghiệp lúa nước giữ vai trò chính; thủ công và thương mại biển phát triển, nhiều thương cảng sầm uất."]],["2. Một số thành tựu văn hoá",["Tín ngưỡng – tôn giáo: Phật giáo, Hin-đu giáo, Hồi giáo cùng tín ngưỡng dân gian.","Chữ viết – văn học: nhiều dân tộc sáng tạo chữ viết riêng trên cơ sở chữ Phạn, chữ Hán; văn học dân gian và viết phong phú.","Kiến trúc – điêu khắc: Ăng-co Vát, Ăng-co Thom (Cam-pu-chia), chùa tháp Pa-gan (Mi-an-ma), Thạt Luổng (Lào)…"]]],"nho":["Từ nửa sau thế kỉ X, các vương quốc Đông Nam Á thịnh đạt.","Nhiều dân tộc sáng tạo chữ viết riêng.","Công trình tiêu biểu: Ăng-co Vát, Pa-gan, Thạt Luổng."],"hoi":["Kể tên một số vương quốc phong kiến lớn ở Đông Nam Á thời kì này.","Việc nhiều quốc gia Đông Nam Á có chữ viết riêng có ý nghĩa gì?","Giới thiệu một công trình kiến trúc tiêu biểu của Đông Nam Á."]},{"so":7,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Vương quốc Lào","trang":[39,41],"nam":1353,"tom":"Năm 1353, Pha Ngừm thống nhất các mường Lào, lập nước Lan Xang. Lan Xang phát triển thịnh vượng trong các thế kỉ XV – XVII, để lại nền văn hoá Phật giáo đặc sắc.","muc":[["1. Sự hình thành và phát triển",["Người Lào Thơng là cư dân cổ, sau có người Lào Lùm di cư đến; tổ chức xã hội sơ khai là các mường cổ.","Năm 1353, Pha Ngừm thống nhất các mường, lên ngôi vua, đặt tên nước là Lan Xang (Triệu Voi).","Thời thịnh vượng: tổ chức bộ máy nhà nước chặt chẽ, quân đội mạnh, giữ quan hệ hoà hiếu với láng giềng, kiên quyết chống xâm lược."]],["2. Một số nét văn hoá",["Phật giáo được tôn sùng, nhiều chùa tháp được xây dựng.","Có chữ viết riêng trên cơ sở chữ của người Khơ-me; văn học dân gian phong phú.","Công trình tiêu biểu: That Luổng (Thạt Luổng) ở Viêng Chăn; lễ hội té nước, nhảy lăm-vông."]]],"nho":["1353: Pha Ngừm lập nước Lan Xang.","Lan Xang thịnh vượng thế kỉ XV – XVII.","Phật giáo giữ vị trí quan trọng; Thạt Luổng là công trình tiêu biểu."],"hoi":["Vương quốc Lan Xang được thành lập như thế nào?","Nêu những nét chính về sự phát triển của Lan Xang thời thịnh vượng.","Kể tên một vài nét văn hoá tiêu biểu của Lào."]},{"so":8,"chuong":"Chương 3. Đông Nam Á từ nửa sau thế kỉ X đến nửa đầu thế kỉ XVI","ten":"Vương quốc Cam-pu-chia","trang":[42,43],"nam":802,"tom":"Năm 802, vua Giay-a-vác-man II thống nhất đất nước, mở ra thời Ăng-co – thời kì phát triển huy hoàng của Cam-pu-chia với những công trình kiến trúc nổi tiếng thế giới.","muc":[["1. Sự hình thành và phát triển",["Từ thế kỉ VI, vương quốc Chân Lạp của người Khơ-me hình thành.","Năm 802, Giay-a-vác-man II thống nhất lãnh thổ, đổi tên nước là Cam-pu-chia, mở đầu thời Ăng-co.","Thời Ăng-co: nông nghiệp có hệ thống thuỷ lợi lớn, lãnh thổ mở rộng; về sau đất nước suy yếu dần."]],["2. Một số nét văn hoá",["Có chữ viết riêng (chữ Khơ-me cổ) bắt nguồn từ chữ Phạn.","Hin-đu giáo và Phật giáo có ảnh hưởng lớn.","Kiến trúc đền tháp Ăng-co Vát, Ăng-co Thom là di sản văn hoá thế giới."]]],"nho":["802: Giay-a-vác-man II mở ra thời Ăng-co.","Ăng-co Vát, Ăng-co Thom là những công trình nổi tiếng."],"hoi":["Trình bày quá trình hình thành và phát triển của vương quốc Cam-pu-chia.","Vì sao thời Ăng-co được coi là thời kì phát triển huy hoàng?"]},{"so":9,"chuong":"Chương 4. Đất nước dưới thời các vương triều Ngô – Đinh – Tiền Lê (939 – 1009)","ten":"Đất nước buổi đầu độc lập (939 – 967)","trang":[45,47],"nam":939,"tom":"Năm 939, Ngô Quyền xưng vương, đóng đô ở Cổ Loa, xây dựng nền độc lập. Sau khi ông mất, đất nước rơi vào loạn 12 sứ quân cho đến khi Đinh Bộ Lĩnh thống nhất vào năm 967.","muc":[["1. Ngô Quyền dựng nền độc lập",["Năm 939, Ngô Quyền bỏ chức Tiết độ sứ, xưng vương, đóng đô ở Cổ Loa.","Đặt triều nghi, chế độ phục sức, đặt các chức quan văn võ; cử tướng lĩnh cai quản các châu.","Việc xưng vương khẳng định nước ta là một quốc gia độc lập, không còn phụ thuộc phương Bắc."]],["2. Loạn 12 sứ quân và sự thống nhất",["Năm 944, Ngô Quyền mất; triều đình suy yếu, các thế lực cát cứ nổi lên, gây nên loạn 12 sứ quân.","Đinh Bộ Lĩnh xây dựng lực lượng ở Hoa Lư, được nhân dân ủng hộ, lần lượt dẹp các sứ quân.","Năm 967, đất nước được thống nhất."]]],"nho":["939: Ngô Quyền xưng vương, đóng đô ở Cổ Loa.","944: Ngô Quyền mất, loạn 12 sứ quân.","967: Đinh Bộ Lĩnh dẹp loạn, thống nhất đất nước."],"hoi":["Việc Ngô Quyền xưng vương có ý nghĩa như thế nào?","Vì sao xảy ra loạn 12 sứ quân?","Đinh Bộ Lĩnh đã thống nhất đất nước như thế nào?"]},{"so":10,"chuong":"Chương 4. Đất nước dưới thời các vương triều Ngô – Đinh – Tiền Lê (939 – 1009)","ten":"Đại Cồ Việt thời Đinh và Tiền Lê (968 – 1009)","trang":[48,50],"nam":968,"tom":"Năm 968, Đinh Bộ Lĩnh lên ngôi hoàng đế, đặt tên nước là Đại Cồ Việt, đóng đô ở Hoa Lư. Năm 981, Lê Hoàn lãnh đạo nhân dân đánh tan quân xâm lược Tống, bảo vệ nền độc lập.","muc":[["1. Tình hình chính trị",["Năm 968, Đinh Bộ Lĩnh lên ngôi (Đinh Tiên Hoàng), đặt quốc hiệu Đại Cồ Việt, đóng đô ở Hoa Lư; định triều nghi, đặt luật pháp nghiêm.","Năm 979, Đinh Tiên Hoàng bị ám hại; vua mới còn nhỏ, nhà Tống lăm le xâm lược. Năm 980, Lê Hoàn lên ngôi, lập nhà Tiền Lê.","Năm 981, quân Tống tiến sang theo hai đường thuỷ, bộ; Lê Hoàn chặn đánh ở sông Bạch Đằng và vùng Chi Lăng, quân Tống thua to.","Chính quyền Tiền Lê được tổ chức chặt chẽ hơn; chia nước thành các lộ, phủ, châu."]],["2. Tình hình xã hội và văn hoá",["Xã hội gồm vua, quan lại, nhà sư; nông dân, thợ thủ công, thương nhân; một số ít nô tì.","Nông nghiệp được chú trọng: vua Lê Hoàn làm lễ cày tịch điền, khai kênh đào.","Phật giáo được đề cao, nhà sư có uy tín, tham gia việc nước; các lễ hội dân gian như đua thuyền, đấu vật phát triển."]]],"nho":["968: Đinh Bộ Lĩnh lập Đại Cồ Việt, kinh đô Hoa Lư.","980: Lê Hoàn lên ngôi; 981: đánh tan quân Tống.","Phật giáo được đề cao, nhà sư tham gia việc nước."],"hoi":["Việc đặt quốc hiệu Đại Cồ Việt và đóng đô ở Hoa Lư có ý nghĩa gì?","Trình bày cuộc kháng chiến chống Tống năm 981 của Lê Hoàn.","Đời sống văn hoá thời Đinh – Tiền Lê có điểm gì nổi bật?"]},{"so":11,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Nhà Lý xây dựng và phát triển đất nước (1009 – 1225)","trang":[52,57],"nam":1010,"tom":"Năm 1009, Lý Công Uẩn lập nhà Lý; năm 1010 dời đô về Thăng Long. Nhà Lý xây dựng bộ máy nhà nước, luật pháp, quân đội vững mạnh, phát triển kinh tế và văn hoá, giáo dục.","muc":[["1. Sự thành lập nhà Lý",["Năm 1009, Lý Công Uẩn được triều thần tôn lên làm vua, lập ra nhà Lý.","Năm 1010, vua ban Chiếu dời đô, chuyển kinh đô từ Hoa Lư về Đại La, đổi tên là Thăng Long.","Năm 1054, nhà Lý đổi tên nước là Đại Việt."]],["2. Xây dựng đất nước",["Bộ máy nhà nước: đứng đầu là vua; giúp vua có các quan văn, võ; cả nước chia thành các lộ, phủ.","Luật pháp: năm 1042 ban hành bộ Hình thư; quân đội gồm cấm quân và quân địa phương, thực hiện chính sách “ngụ binh ư nông”.","Đối nội: mềm dẻo với các tù trưởng miền núi; đối ngoại: giữ hoà hiếu nhưng kiên quyết bảo vệ chủ quyền."]],["3. Kinh tế, xã hội",["Nông nghiệp: khuyến khích khai hoang, đắp đê (đê Cơ Xá năm 1108), lễ cày tịch điền.","Thủ công: dệt (năm 1040 dệt được gấm vóc), gốm, đúc đồng phát triển; thương nghiệp có trao đổi trong nước và với nước ngoài, cảng Vân Đồn.","Xã hội gồm vua quan, địa chủ, nông dân, thợ thủ công, thương nhân, nô tì."]],["4. Văn hoá, giáo dục",["Phật giáo phát triển mạnh, chùa tháp được xây dựng nhiều: chùa Một Cột, tháp Báo Thiên.","Năm 1070 dựng Văn Miếu; năm 1075 mở khoa thi đầu tiên; năm 1076 lập Quốc Tử Giám.","Văn học chữ Hán phát triển; nghệ thuật điêu khắc, kiến trúc đặc sắc."]]],"nho":["1009: nhà Lý thành lập; 1010: dời đô về Thăng Long; 1054: quốc hiệu Đại Việt.","1042: bộ Hình thư; chính sách “ngụ binh ư nông”.","1070 Văn Miếu, 1075 khoa thi đầu tiên, 1076 Quốc Tử Giám."],"hoi":["Vì sao Lý Công Uẩn quyết định dời đô về Đại La?","Nhà Lý đã làm gì để xây dựng bộ máy nhà nước, luật pháp và quân đội?","Nêu những thành tựu về giáo dục thời Lý."]},{"so":12,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Cuộc kháng chiến chống quân xâm lược Tống (1075 – 1077)","trang":[58,61],"nam":1075,"tom":"Dưới sự chỉ huy của Lý Thường Kiệt, quân dân Đại Việt chủ động tấn công trước để chặn thế mạnh của giặc (1075), rồi lập phòng tuyến sông Như Nguyệt đánh bại quân Tống (1077).","muc":[["1. Giai đoạn thứ nhất (1075): tiến công để tự vệ",["Nhà Tống chuẩn bị xâm lược Đại Việt; Lý Thường Kiệt chủ trương “ngồi yên đợi giặc không bằng đem quân ra trước để chặn thế mạnh của giặc”.","Cuối năm 1075, quân Lý bất ngờ tấn công các căn cứ tập kết lương thảo, khí giới của quân Tống ở Khâm Châu, Liêm Châu, Ung Châu rồi rút về nước."]],["2. Giai đoạn thứ hai (1076 – 1077): phòng tuyến sông Như Nguyệt",["Lý Thường Kiệt cho xây dựng phòng tuyến trên bờ nam sông Như Nguyệt (sông Cầu), đóng cọc, đắp luỹ.","Năm 1077, quân Tống do Quách Quỳ chỉ huy kéo sang, nhiều lần vượt sông tấn công nhưng đều thất bại.","Tương truyền bài thơ “Nam quốc sơn hà” vang lên, cổ vũ tinh thần quân ta. Quân ta phản công, quân Tống thua to.","Lý Thường Kiệt chủ động giảng hoà để kết thúc chiến tranh; quân Tống rút về nước."]],["3. Ý nghĩa",["Bảo vệ vững chắc nền độc lập của Đại Việt.","Thể hiện nghệ thuật quân sự độc đáo: tiến công để tự vệ, chặn giặc bằng phòng tuyến, kết thúc chiến tranh bằng giảng hoà."]]],"nho":["1075: tiến công Khâm Châu, Liêm Châu, Ung Châu.","1077: phòng tuyến sông Như Nguyệt, quân Tống thất bại.","Lý Thường Kiệt chủ động giảng hoà để giữ hoà hiếu lâu dài."],"hoi":["Vì sao Lý Thường Kiệt chủ động tấn công sang đất Tống?","Trình bày trận chiến trên phòng tuyến sông Như Nguyệt.","Việc chủ động giảng hoà của Lý Thường Kiệt có ý nghĩa gì?"],"sa_ban":{"ten":"Sa bàn 3D Phòng tuyến Như Nguyệt 1077","url":"khong-gian/engine/2.1.0/sa-ban.html?goi=nhu-nguyet-1077"}},{"so":13,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Đại Việt thời Trần (1226 – 1400)","trang":[62,67],"nam":1226,"tom":"Năm 1226, nhà Trần thành lập, củng cố bộ máy nhà nước với chế độ Thái thượng hoàng, phát triển kinh tế, xã hội và đạt nhiều thành tựu văn hoá rực rỡ.","muc":[["1. Sự thành lập nhà Trần và tổ chức nhà nước",["Cuối thời Lý, triều đình suy yếu; năm 1226, Lý Chiêu Hoàng nhường ngôi cho Trần Cảnh, nhà Trần thành lập.","Thực hiện chế độ Thái thượng hoàng: vua cha nhường ngôi sớm cho con, cùng trông coi việc nước.","Cả nước chia thành 12 lộ; ban hành bộ Quốc triều hình luật; quân đội theo chủ trương “quân lính cốt tinh nhuệ, không cốt đông”."]],["2. Kinh tế, xã hội",["Nông nghiệp: khuyến khích khai hoang, lập điền trang; đặt chức Hà đê sứ trông coi đê điều.","Thủ công, thương nghiệp phát triển; Thăng Long có nhiều phường nghề, chợ.","Xã hội: tầng lớp quý tộc nắm quyền; nông dân, thợ thủ công, thương nhân; nông nô, nô tì làm việc trong điền trang."]],["3. Văn hoá",["Tư tưởng, tôn giáo: Phật giáo phát triển, vua Trần Nhân Tông lập Thiền phái Trúc Lâm; Nho giáo ngày càng được coi trọng.","Giáo dục, khoa cử: tổ chức nhiều khoa thi; Quốc Tử Giám mở rộng.","Khoa học: Quốc sử viện, bộ Đại Việt sử kí của Lê Văn Hưu; y học có danh y Tuệ Tĩnh.","Văn học, nghệ thuật: Hịch tướng sĩ của Trần Quốc Tuấn; chữ Nôm được dùng; tháp Phổ Minh, kiến trúc, điêu khắc đặc sắc."]]],"nho":["1226: nhà Trần thành lập; chế độ Thái thượng hoàng.","Quốc triều hình luật; Hà đê sứ; quân đội tinh nhuệ.","Thiền phái Trúc Lâm; Đại Việt sử kí của Lê Văn Hưu; Hịch tướng sĩ."],"hoi":["Chế độ Thái thượng hoàng có tác dụng gì?","Nêu những nét chính về kinh tế thời Trần.","Kể tên một số thành tựu văn hoá tiêu biểu thời Trần."]},{"so":14,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Ba lần kháng chiến chống quân xâm lược Mông – Nguyên","trang":[68,73],"nam":1258,"tom":"Trong các năm 1258, 1285 và 1287 – 1288, quân dân Đại Việt dưới sự lãnh đạo của nhà Trần ba lần đánh bại quân xâm lược Mông – Nguyên, đội quân mạnh nhất thế giới thời đó.","muc":[["1. Lần thứ nhất (1258)",["Đầu năm 1258, quân Mông Cổ tiến vào Đại Việt; sau trận Bình Lệ Nguyên, quân ta rút lui để bảo toàn lực lượng, thực hiện “vườn không nhà trống”.","Trần Thủ Độ khẳng định: “Đầu thần chưa rơi xuống đất, xin bệ hạ đừng lo”.","Quân ta phản công ở Đông Bộ Đầu, quân Mông Cổ phải rút chạy."]],["2. Lần thứ hai (1285)",["Nhà Trần mở Hội nghị Bình Than (1282) bàn kế đánh giặc, Hội nghị Diên Hồng (1285) hỏi ý các bô lão; quân sĩ thích hai chữ “Sát Thát” lên cánh tay.","Quân Nguyên do Thoát Hoan chỉ huy tiến vào; quân ta tạm rút khỏi Thăng Long.","Giữa năm 1285, quân ta phản công thắng lớn ở Tây Kết, Hàm Tử, Chương Dương, Vạn Kiếp; quân Nguyên thua chạy."]],["3. Lần thứ ba (1287 – 1288)",["Trần Khánh Dư đánh tan đoàn thuyền lương của giặc ở Vân Đồn, làm quân Nguyên lâm vào cảnh thiếu lương.","Trần Quốc Tuấn bố trí trận địa cọc trên sông Bạch Đằng; tháng 4/1288, đoàn thuyền giặc bị tiêu diệt, Ô Mã Nhi bị bắt."]],["4. Nguyên nhân thắng lợi và ý nghĩa",["Toàn dân tham gia đánh giặc; vua tôi đoàn kết; sự lãnh đạo tài giỏi của vua Trần và các tướng như Trần Quốc Tuấn, Trần Quang Khải, Trần Thủ Độ.","Đập tan ý chí xâm lược của Mông – Nguyên, bảo vệ nền độc lập; để lại bài học quý về đoàn kết và nghệ thuật quân sự."]]],"nho":["Ba lần kháng chiến: 1258, 1285, 1287 – 1288.","Hội nghị Bình Than, Diên Hồng; hai chữ “Sát Thát”.","1288: chiến thắng Bạch Đằng do Trần Quốc Tuấn chỉ huy."],"hoi":["Trình bày diễn biến chính của ba lần kháng chiến chống Mông – Nguyên.","Nêu nguyên nhân thắng lợi của ba lần kháng chiến.","Câu nói của Trần Thủ Độ thể hiện tinh thần gì?"]},{"so":15,"chuong":"Chương 5. Đại Việt thời Lý – Trần – Hồ (1009 – 1407)","ten":"Nước Đại Ngu thời Hồ (1400 – 1407)","trang":[74,76],"nam":1400,"tom":"Năm 1400, Hồ Quý Ly lập nhà Hồ, đổi tên nước là Đại Ngu và tiến hành nhiều cải cách. Cuộc kháng chiến chống quân Minh của nhà Hồ thất bại vào năm 1407.","muc":[["1. Nhà Hồ thành lập và cải cách",["Cuối thế kỉ XIV, nhà Trần suy yếu; năm 1400, Hồ Quý Ly phế vua Trần, lập nhà Hồ, đổi tên nước là Đại Ngu.","Chính trị, quân sự: thay quan lại họ Trần bằng người tài; tăng cường quân đội; xây thành Tây Đô (Thanh Hoá).","Kinh tế, xã hội: ban hành chính sách hạn điền, hạn nô; phát hành tiền giấy “Thông bảo hội sao”; thống nhất đo lường.","Văn hoá, giáo dục: dịch sách chữ Hán ra chữ Nôm, đề cao chữ Nôm; sửa đổi chế độ thi cử."]],["2. Cuộc kháng chiến chống quân Minh",["Năm 1406, quân Minh xâm lược Đại Ngu.","Nhà Hồ không đoàn kết được toàn dân, chỉ dựa vào thành luỹ để phòng thủ; năm 1407 kháng chiến thất bại.","Hồ Nguyên Trừng nói: “Thần không sợ đánh, chỉ sợ lòng dân không theo” – nêu rõ nguyên nhân thất bại."]]],"nho":["1400: nhà Hồ thành lập, quốc hiệu Đại Ngu.","Cải cách: hạn điền, hạn nô, tiền giấy, đề cao chữ Nôm.","1407: kháng chiến chống Minh thất bại vì không được lòng dân."],"hoi":["Nêu những nội dung chính trong cải cách của Hồ Quý Ly.","Vì sao cuộc kháng chiến chống quân Minh của nhà Hồ thất bại?","Thành Tây Đô có giá trị gì? Ngày nay thành này được công nhận là gì?"]},{"so":16,"chuong":"Chương 6. Khởi nghĩa Lam Sơn và Đại Việt thời Lê sơ (1418 – 1527)","ten":"Khởi nghĩa Lam Sơn (1418 – 1427)","trang":[78,82],"nam":1418,"tom":"Năm 1418, Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn. Sau mười năm chiến đấu gian khổ, nghĩa quân giành toàn thắng năm 1427, giải phóng đất nước khỏi ách đô hộ của nhà Minh.","muc":[["1. Lê Lợi dựng cờ khởi nghĩa",["Dưới ách đô hộ của nhà Minh, nhân dân bị bóc lột nặng nề.","Đầu năm 1418, Lê Lợi cùng Nguyễn Trãi và các hào kiệt dựng cờ khởi nghĩa ở Lam Sơn (Thanh Hoá), xưng Bình Định Vương."]],["2. Diễn biến chính",["1418 – 1423: những năm đầu khó khăn, nghĩa quân nhiều lần bị vây ở núi Chí Linh; Lê Lai liều mình cứu chúa; có lúc phải tạm hoà với giặc.","1424 – 1425: theo kế của Nguyễn Chích, nghĩa quân chuyển vào Nghệ An, rồi giải phóng Tân Bình, Thuận Hoá; giành thắng lợi đầu tiên.","1426 – 1427: tiến quân ra Bắc; thắng lớn ở Tốt Động – Chúc Động (1426); trận Chi Lăng – Xương Giang (1427), Liễu Thăng tử trận, viện binh Minh bị tiêu diệt.","Cuối năm 1427, Hội thề Đông Quan; quân Minh rút về nước. Nguyễn Trãi viết Bình Ngô đại cáo."]],["3. Nguyên nhân thắng lợi và ý nghĩa",["Nhân dân đồng lòng ủng hộ; lòng yêu nước, ý chí bất khuất; đường lối đúng đắn và tài chỉ huy của Lê Lợi, Nguyễn Trãi.","Kết thúc 20 năm đô hộ của nhà Minh, mở ra thời kì phát triển mới cho Đại Việt."]]],"nho":["1418: Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn.","1426 Tốt Động – Chúc Động; 1427 Chi Lăng – Xương Giang.","Bình Ngô đại cáo của Nguyễn Trãi tuyên bố nền độc lập."],"hoi":["Khởi nghĩa Lam Sơn bùng nổ như thế nào?","Trình bày các giai đoạn phát triển của cuộc khởi nghĩa.","Vì sao khởi nghĩa Lam Sơn giành được thắng lợi?"]},{"so":17,"chuong":"Chương 6. Khởi nghĩa Lam Sơn và Đại Việt thời Lê sơ (1418 – 1527)","ten":"Đại Việt thời Lê sơ (1428 – 1527)","trang":[83,88],"nam":1428,"tom":"Năm 1428, Lê Lợi lên ngôi, lập nhà Lê sơ. Dưới thời Lê Thánh Tông, Đại Việt đạt tới thời thịnh trị với bộ máy nhà nước hoàn chỉnh, luật Hồng Đức và nền giáo dục khoa cử phát triển.","muc":[["1. Tình hình chính trị",["Năm 1428, Lê Lợi lên ngôi, khôi phục quốc hiệu Đại Việt, đóng đô ở Thăng Long (Đông Kinh).","Lê Thánh Tông (1460 – 1497) cải cách: bỏ một số chức quan lớn, vua nắm mọi quyền; chia cả nước thành 13 đạo thừa tuyên.","Ban hành bộ Quốc triều hình luật (luật Hồng Đức), có điểm tiến bộ như bảo vệ quyền lợi phụ nữ.","Kiên quyết bảo vệ chủ quyền lãnh thổ: “một thước núi, một tấc sông của ta, lẽ nào lại tự tiện vứt bỏ”."]],["2. Kinh tế, xã hội",["Nông nghiệp: chính sách quân điền, khuyến khích khai hoang, đắp đê.","Thủ công nghiệp, thương nghiệp phát triển; nhiều làng nghề, chợ.","Xã hội gồm vua quan, địa chủ, nông dân, thợ thủ công, thương nhân, nô tì; số nô tì giảm dần."]],["3. Văn hoá, giáo dục và danh nhân",["Nho giáo chiếm vị trí độc tôn; giáo dục, khoa cử rất phát triển; năm 1484 bắt đầu dựng bia Tiến sĩ ở Văn Miếu.","Nguyễn Trãi: nhà quân sự, chính trị, nhà văn hoá lớn (Bình Ngô đại cáo, Quốc âm thi tập).","Lê Thánh Tông: vị vua anh minh, lập Hội Tao đàn, nhiều tác phẩm văn học.","Ngô Sĩ Liên biên soạn Đại Việt sử kí toàn thư; Lương Thế Vinh viết Đại thành toán pháp."]]],"nho":["1428: nhà Lê sơ thành lập.","Lê Thánh Tông: 13 đạo thừa tuyên, luật Hồng Đức.","1484: dựng bia Tiến sĩ; danh nhân Nguyễn Trãi, Lê Thánh Tông, Ngô Sĩ Liên, Lương Thế Vinh."],"hoi":["Trình bày những cải cách của vua Lê Thánh Tông.","Bộ luật Hồng Đức có những điểm tiến bộ nào?","Giới thiệu một danh nhân văn hoá thời Lê sơ."]},{"so":18,"chuong":"Chương 7. Vùng đất phía Nam Việt Nam từ đầu thế kỉ X đến đầu thế kỉ XVI","ten":"Vương quốc Chăm-pa và vùng đất Nam Bộ từ đầu thế kỉ X đến đầu thế kỉ XVI","trang":[90,94],"nam":null,"tom":"Từ thế kỉ X, Chăm-pa bước vào thời kì Vi-giay-a với kinh đô ở Đồ Bàn, có nền kinh tế, văn hoá phát triển nhưng gặp nhiều khó khăn vì chiến tranh. Vùng đất Nam Bộ thời kì này dân cư còn thưa thớt.","muc":[["1. Vương quốc Chăm-pa",["Năm 988, một quý tộc Chăm lập vương triều Vi-giay-a, kinh đô chuyển về Vi-giay-a (Đồ Bàn, Bình Định ngày nay).","Chăm-pa nhiều lần xảy ra chiến tranh với Chân Lạp và xung đột với Đại Việt; năm 1069 cắt ba châu Bố Chính, Địa Lý, Ma Linh cho Đại Việt.","Kinh tế: trồng lúa nước, khai thác lâm sản, buôn bán đường biển; văn hoá: theo Hin-đu giáo, Phật giáo, xây dựng nhiều đền tháp (tháp Bánh Ít, tháp Dương Long…)."]],["2. Vùng đất Nam Bộ",["Sau khi Phù Nam sụp đổ (đầu thế kỉ VII), Nam Bộ thuộc quyền kiểm soát của Chân Lạp.","Dân cư thưa thớt, nhiều vùng hoang vu, sình lầy; cư dân sống chủ yếu bằng nông nghiệp, khai thác sản vật."]]],"nho":["988: vương triều Vi-giay-a của Chăm-pa; kinh đô Đồ Bàn.","Chăm-pa có kinh tế biển và văn hoá đền tháp phát triển.","Nam Bộ thời kì này thuộc Chân Lạp, dân cư thưa thớt."],"hoi":["Nêu những nét chính về chính trị, kinh tế, văn hoá của Chăm-pa từ thế kỉ X đến đầu thế kỉ XVI.","Vùng đất Nam Bộ thời kì này có đặc điểm gì?"]},{"so":"CĐ1","chuong":"Chủ đề chung","ten":"Các cuộc đại phát kiến địa lí","trang":[166,169],"nam":1492,"tom":"Chủ đề tích hợp Lịch sử và Địa lí về các chuyến thám hiểm lớn cuối thế kỉ XV – đầu thế kỉ XVI, tiêu biểu là chuyến đi của C. Cô-lôm-bô và Ph. Ma-gien-lan, cùng tác động của chúng tới thế giới.","muc":[["1. Cô-lôm-bô và cuộc thám hiểm tìm ra châu Mỹ",["Năm 1492, C. Cô-lôm-bô được hoàng gia Tây Ban Nha tài trợ, đi về phía tây Đại Tây Dương với ý định tới Ấn Độ.","Đoàn thám hiểm đến được các đảo vùng Ca-ri-bê, mở ra con đường đến châu Mỹ cho người châu Âu."]],["2. Ma-gien-lan và chuyến đi vòng quanh Trái Đất",["Năm 1519, Ph. Ma-gien-lan dẫn đoàn thuyền vượt Đại Tây Dương, qua eo biển ở cực nam châu Mỹ (sau mang tên ông), vào Thái Bình Dương.","Ma-gien-lan bị giết ở Phi-líp-pin; những người còn lại tiếp tục hành trình, về đến Tây Ban Nha năm 1522, chứng minh Trái Đất hình cầu."]],["3. Tác động",["Mở rộng hiểu biết về Trái Đất, thúc đẩy giao lưu kinh tế, văn hoá giữa các châu lục.","Mở đầu quá trình xâm chiếm, cướp bóc thuộc địa và buôn bán nô lệ."]]],"nho":["1492: Cô-lôm-bô đến châu Mỹ.","1519 – 1522: chuyến đi vòng quanh Trái Đất của đoàn Ma-gien-lan.","Phát kiến địa lí mở rộng hiểu biết nhưng kéo theo chủ nghĩa thực dân."],"hoi":["Kể lại hành trình của Cô-lôm-bô hoặc Ma-gien-lan.","Chuyến đi của Ma-gien-lan chứng minh điều gì?","Các cuộc đại phát kiến địa lí tác động thế nào tới thế giới?"]},{"so":"CĐ2","chuong":"Chủ đề chung","ten":"Đô thị: lịch sử và hiện tại","trang":[170,174],"nam":null,"tom":"Chủ đề tích hợp về sự ra đời và vai trò của đô thị từ thời cổ đại đến trung đại, gắn với các nền văn minh phương Đông, Hy Lạp – La Mã và châu Âu trung đại.","muc":[["1. Đô thị thời cổ đại",["Ở phương Đông, các làng ven sông lớn mở rộng thành những khu dân cư đông đúc, hình thành đô thị như Ba-bi-lon (Lưỡng Hà), Mem-phít (Ai Cập), Mô-hen-giô Đa-rô (Ấn Độ). Đô thị là trung tâm chính trị, kinh tế, văn hoá của các quốc gia cổ đại.","Ở Hy Lạp, La Mã, đô thị gắn với thủ công nghiệp, thương nghiệp đường biển; là nơi ra đời thể chế dân chủ A-ten và nhiều thành tựu văn hoá."]],["2. Đô thị châu Âu thời trung đại",["Từ thế kỉ XI, thợ thủ công, thương nhân lập ra các thành thị; thị dân lập phường hội, thương hội.","Thương nhân buôn bán khắp châu Âu, góp phần phá vỡ kinh tế tự cấp tự túc của lãnh địa, thúc đẩy kinh tế hàng hoá và văn hoá phát triển."]],["3. Đô thị hôm nay",["Đô thị ngày nay là trung tâm kinh tế, văn hoá, khoa học; đối mặt với các vấn đề dân số, môi trường, giao thông.","Tìm hiểu lịch sử đô thị giúp ta hiểu và có ý thức gìn giữ di sản của thành phố nơi mình sống."]]],"nho":["Đô thị cổ đại: Ba-bi-lon, Mem-phít, Mô-hen-giô Đa-rô, A-ten, Rô-ma.","Thành thị trung đại thúc đẩy kinh tế hàng hoá.","Đô thị là trung tâm chính trị, kinh tế, văn hoá qua mọi thời kì."],"hoi":["Các đô thị cổ ở phương Đông có vai trò gì?","Thương nhân có vai trò thế nào trong các đô thị châu Âu trung đại?","Giới thiệu lịch sử một đô thị ở Việt Nam mà em biết."]}]}}};
